for filename, encoded in FILES.items():
    path = Path(filename)
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if path.exists():
        backup = path.with_name(
            path.name
            + ".before_org_v66.bak"
        )

        if not backup.exists():
            backup.write_text(
                path.read_text(
                    encoding="utf-8"
                ),
                encoding="utf-8",
            )

    path.write_bytes(
        base64.b64decode(
            encoded
        )
    )

    print(
        "OK:",
        filename,
    )

print("")
print("Archivos V66 instalados.")
